// --- 2-PC Peer-to-Peer Network Manager ---
class NetworkManager {
  constructor(game) {
    this.game = game;
    this.role = null; // 'host' or 'guest'
    this.connected = false;

    this.peer = null;
    this.conn = null;
    this.roomCode = '';

    this.rtcPeer = null;
    this.dataChannel = null;
  }

  disconnect() {
    this.connected = false;
    this.role = null;
    if (this.conn) {
      try { this.conn.close(); } catch (e) {}
      this.conn = null;
    }
    if (this.peer) {
      try { this.peer.destroy(); } catch (e) {}
      this.peer = null;
    }
    if (this.dataChannel) {
      try { this.dataChannel.close(); } catch (e) {}
      this.dataChannel = null;
    }
    if (this.rtcPeer) {
      try { this.rtcPeer.close(); } catch (e) {}
      this.rtcPeer = null;
    }
    this.game.onNetworkStatusChange(false, 'Multiplayer Lobby');
  }

  createRoom() {
    this.disconnect();
    if (typeof window.Peer === 'undefined') {
      this.game.setMpBanner('⚠️ PeerJS CDN not reachable (offline). Switch to the "Offline LAN / Manual Key" tab!');
      return;
    }

    this.role = 'host';
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    let code = '';
    for (let i = 0; i < 6; i++) {
      code += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    this.roomCode = code;
    const peerId = `stickman-strike-${code}`;

    document.getElementById('hostRoomCodeWrap').style.display = 'flex';
    document.getElementById('hostRoomCodeText').textContent = code;
    document.getElementById('hostWaitingText').textContent = '⏳ Creating room...';

    this.peer = new window.Peer(peerId);

    this.peer.on('open', () => {
      document.getElementById('hostWaitingText').textContent = '⏳ Waiting for PC 2 to enter code & join...';
      this.game.setMpBanner(`🏠 Room ${code} created! Share "${code}" with PC 2.`);
    });

    this.peer.on('connection', (conn) => {
      this.conn = conn;
      this.setupPeerConnection(conn);
    });

    this.peer.on('error', (err) => {
      this.game.setMpBanner(`⚠️ Connection error: ${err.type || err.message}`);
    });
  }

  joinRoom(rawCode) {
    const code = (rawCode || '').trim().toUpperCase();
    if (code.length < 4) {
      this.game.setMpBanner('⚠️ Please enter a valid Room Code from PC 1.');
      return;
    }
    this.disconnect();
    if (typeof window.Peer === 'undefined') {
      this.game.setMpBanner('⚠️ PeerJS CDN not reachable (offline). Switch to the "Offline LAN / Manual Key" tab!');
      return;
    }

    this.role = 'guest';
    this.roomCode = code;
    document.getElementById('guestStatusText').textContent = `⏳ Connecting to Room ${code}...`;
    this.game.setMpBanner(`🚀 Connecting to PC 1 (Room ${code})...`);

    this.peer = new window.Peer();
    this.peer.on('open', () => {
      const conn = this.peer.connect(`stickman-strike-${code}`, { reliable: false });
      this.conn = conn;
      this.setupPeerConnection(conn);
    });

    this.peer.on('error', (err) => {
      document.getElementById('guestStatusText').textContent = '❌ Could not find room. Check the code!';
      this.game.setMpBanner(`⚠️ Error: ${err.type || err.message}`);
    });
  }

  setupPeerConnection(conn) {
    conn.on('open', () => {
      this.connected = true;
      const roleLabel = this.role === 'host' ? 'PC 1 (SHADOW)' : 'PC 2 (VIPER)';
      this.game.onNetworkStatusChange(true, `🟢 Connected: ${roleLabel}`);
      this.game.setMpBanner(`🟢 Connected! You are ${roleLabel}. Launching match!`);
      setTimeout(() => {
        document.getElementById('multiplayerModal').classList.remove('open');
        this.game.enterArenaScreen('online');
        if (this.role === 'host') {
          this.game.startMatch();
        }
      }, 500);
    });

    conn.on('data', (data) => {
      this.game.onNetworkData(data);
    });

    conn.on('close', () => {
      this.connected = false;
      this.game.onNetworkStatusChange(false, '🔴 Disconnected');
      this.game.setMpBanner('🔴 Opponent disconnected.');
    });
  }

  async createLanOffer() {
    this.disconnect();
    this.role = 'host';
    this.rtcPeer = new RTCPeerConnection({
      iceServers: [{ urls: 'stun:stun.l.google.com:19302' }]
    });

    this.dataChannel = this.rtcPeer.createDataChannel('stickman-lan');
    this.setupRtcDataChannel(this.dataChannel);

    this.rtcPeer.onicecandidate = (e) => {
      if (!e.candidate && this.rtcPeer.localDescription) {
        const token = btoa(JSON.stringify(this.rtcPeer.localDescription));
        document.getElementById('lanOfferOut').value = token;
        this.game.setMpBanner('✅ Step 1 Done: Copy the Offer Key above and send it to PC 2!');
      }
    };

    const offer = await this.rtcPeer.createOffer();
    await this.rtcPeer.setLocalDescription(offer);
  }

  async createLanAnswer(offerToken) {
    try {
      const desc = JSON.parse(atob(offerToken.trim()));
      this.disconnect();
      this.role = 'guest';
      this.rtcPeer = new RTCPeerConnection({
        iceServers: [{ urls: 'stun:stun.l.google.com:19302' }]
      });

      this.rtcPeer.ondatachannel = (e) => {
        this.dataChannel = e.channel;
        this.setupRtcDataChannel(this.dataChannel);
      };

      this.rtcPeer.onicecandidate = (e) => {
        if (!e.candidate && this.rtcPeer.localDescription) {
          const token = btoa(JSON.stringify(this.rtcPeer.localDescription));
          document.getElementById('lanAnswerOut').value = token;
          this.game.setMpBanner('✅ Step 2 Done: Copy the Answer Key above and send it back to PC 1!');
        }
      };

      await this.rtcPeer.setRemoteDescription(desc);
      const answer = await this.rtcPeer.createAnswer();
      await this.rtcPeer.setLocalDescription(answer);
    } catch (err) {
      this.game.setMpBanner('⚠️ Invalid Offer Key pasted. Make sure you copied the full string!');
    }
  }

  async acceptLanAnswer(answerToken) {
    try {
      const desc = JSON.parse(atob(answerToken.trim()));
      if (!this.rtcPeer) return;
      await this.rtcPeer.setRemoteDescription(desc);
    } catch (err) {
      this.game.setMpBanner('⚠️ Invalid Answer Key pasted.');
    }
  }

  setupRtcDataChannel(ch) {
    ch.onopen = () => {
      this.connected = true;
      const roleLabel = this.role === 'host' ? 'PC 1 (SHADOW)' : 'PC 2 (VIPER)';
      this.game.onNetworkStatusChange(true, `🟢 LAN: ${roleLabel}`);
      this.game.setMpBanner(`🟢 Direct LAN Connected! You are ${roleLabel}.`);
      setTimeout(() => {
        document.getElementById('multiplayerModal').classList.remove('open');
        this.game.enterArenaScreen('online');
        if (this.role === 'host') {
          this.game.startMatch();
        }
      }, 500);
    };

    ch.onmessage = (e) => {
      try {
        const data = JSON.parse(e.data);
        this.game.onNetworkData(data);
      } catch (err) {}
    };

    ch.onclose = () => {
      this.connected = false;
      this.game.onNetworkStatusChange(false, '🔴 LAN Disconnected');
    };
  }

  send(payload) {
    if (!this.connected) return;
    if (this.conn && this.conn.open) {
      this.conn.send(payload);
    } else if (this.dataChannel && this.dataChannel.readyState === 'open') {
      this.dataChannel.send(JSON.stringify(payload));
    }
  }
}

// --- Fighter Class ---
class Fighter {
  constructor(game, id, name, x, color, facing = 1, isAI = false) {
    this.game = game;
    this.id = id;
    this.name = name;
    this.x = x;
    this.y = 560;
    this.vx = 0;
    this.vy = 0;
    this.groundY = 560;
    this.color = color;
    this.facing = facing;
    this.isAI = isAI;

    this.hp = 100;
    this.displayHp = 100;
    this.superMeter = 0;
    this.roundsWon = 0;
    this.maxCombo = 0;

    this.state = 'idle';
    this.stateTime = 0;
    this.isGrounded = true;
    this.isCrouching = false;
    this.isGuarding = false;
    this.isDashing = false;
    this.blockStunTimer = 0;
    this.hitstunDuration = 0;

    this.currentMove = null;
    this.moveFrame = 0;
    this.hasHitCurrentMove = false;
    this.comboCount = 0;
    this.comboTimer = 0;

    this.joints = this.getDefaultJoints();
  }

  resetRound(x, facing) {
    this.x = x;
    this.y = this.groundY;
    this.vx = 0;
    this.vy = 0;
    this.facing = facing;
    this.hp = 100;
    this.displayHp = 100;
    this.state = 'idle';
    this.stateTime = 0;
    this.isGrounded = true;
    this.currentMove = null;
    this.moveFrame = 0;
    this.hasHitCurrentMove = false;
    this.isGuarding = false;
    this.isCrouching = false;
    this.isDashing = false;
    this.blockStunTimer = 0;
    this.comboCount = 0;
    this.comboTimer = 0;
    this.joints = this.getDefaultJoints();
  }

  getDefaultJoints() {
    return {
      pelvis: { x: 0, y: -90 },
      chest: { x: 0, y: -140 },
      head: { x: 0, y: -175 },
      shoulderL: { x: -8, y: -135 },
      elbowL: { x: 12, y: -115 },
      handL: { x: 26, y: -135 },
      shoulderR: { x: 8, y: -135 },
      elbowR: { x: -4, y: -110 },
      handR: { x: 14, y: -130 },
      hipL: { x: -10, y: -90 },
      kneeL: { x: 10, y: -45 },
      footL: { x: 14, y: 0 },
      hipR: { x: 10, y: -90 },
      kneeR: { x: -14, y: -45 },
      footR: { x: -16, y: 0 }
    };
  }

  serialize() {
    return {
      x: Math.round(this.x * 10) / 10,
      y: Math.round(this.y * 10) / 10,
      facing: this.facing,
      hp: Math.round(this.hp * 10) / 10,
      displayHp: Math.round(this.displayHp * 10) / 10,
      superMeter: Math.round(this.superMeter),
      roundsWon: this.roundsWon,
      maxCombo: this.maxCombo,
      state: this.state,
      stateTime: this.stateTime,
      isGrounded: this.isGrounded,
      isCrouching: this.isCrouching,
      isGuarding: this.isGuarding,
      moveId: this.currentMove ? this.currentMove.id : null,
      moveFrame: this.moveFrame
    };
  }

  applySnapshot(snap) {
    this.x = snap.x;
    this.y = snap.y;
    this.facing = snap.facing;
    this.hp = snap.hp;
    this.displayHp = snap.displayHp;
    this.superMeter = snap.superMeter;
    this.roundsWon = snap.roundsWon;
    this.maxCombo = snap.maxCombo;
    this.state = snap.state;
    this.stateTime = snap.stateTime;
    this.isGrounded = snap.isGrounded;
    this.isCrouching = snap.isCrouching;
    this.isGuarding = snap.isGuarding;
    this.currentMove = snap.moveId ? MOVES[snap.moveId] : null;
    this.moveFrame = snap.moveFrame;
    this.computeJoints();
  }

  update(inputState, opponent) {
    this.stateTime++;

    if (this.isGrounded && !['attack', 'hurt', 'knockdown', 'dead', 'dash'].includes(this.state)) {
      if (Math.abs(opponent.x - this.x) > 8) {
        this.facing = this.x < opponent.x ? 1 : -1;
      }
    }

    if (this.comboTimer > 0) {
      this.comboTimer--;
      if (this.comboTimer <= 0) {
        this.comboCount = 0;
      }
    }

    if (this.displayHp > this.hp) {
      this.displayHp = Math.max(this.hp, this.displayHp - 0.5);
    }

    if (this.blockStunTimer > 0) {
      this.blockStunTimer--;
    }

    if (!this.isGrounded) {
      this.vy += 0.82;
      this.x += this.vx;
      this.y += this.vy;

      if (this.y >= this.groundY) {
        this.y = this.groundY;
        this.vy = 0;
        this.isGrounded = true;
        this.game.spawnDust(this.x, this.y, 6);

        if (this.state === 'jump' || this.state === 'hop') {
          this.state = 'idle';
          this.vx *= 0.4;
          this.game.updateMoveHUD(this.id, 'READY');
        } else if (this.state === 'attack' && this.currentMove && this.currentMove.id === 'air_kick') {
          this.state = 'idle';
          this.currentMove = null;
          this.game.updateMoveHUD(this.id, 'READY');
        }
      }
    } else {
      this.vx *= (this.state === 'dash') ? 0.92 : 0.76;
      this.x += this.vx;
    }

    if (this.state !== 'dash' && this.isGrounded && opponent.isGrounded && this.state !== 'dead' && opponent.state !== 'dead') {
      const minDist = 42;
      const dist = Math.abs(this.x - opponent.x);
      if (dist < minDist) {
        const push = (minDist - dist) * 0.5;
        if (this.x < opponent.x) {
          this.x -= push;
          opponent.x += push;
        } else {
          this.x += push;
          opponent.x -= push;
        }
      }
    }

    this.x = Math.max(60, Math.min(1220, this.x));

    switch (this.state) {
      case 'idle':
      case 'walk':
      case 'crouch':
      case 'block':
        this.handleStandardActions(inputState, opponent);
        break;

      case 'jump':
      case 'hop':
        if (inputState.left) this.vx = Math.max(-7.5, this.vx - 0.45);
        if (inputState.right) this.vx = Math.min(7.5, this.vx + 0.45);

        if (inputState.lowKick || inputState.roundhouse || inputState.jab || inputState.cross || inputState.hook) {
          this.startMove(MOVES.air_kick);
        } else if (inputState.flyingKnee) {
          this.startMove(MOVES.flying_knee);
        }
        break;

      case 'dash':
        if (this.stateTime > 11) {
          this.state = 'idle';
          this.isDashing = false;
        }
        break;

      case 'attack':
        this.updateAttack(opponent);
        break;

      case 'hurt':
        if (this.stateTime > this.hitstunDuration) {
          this.state = 'idle';
        }
        break;

      case 'knockdown':
        if (this.isGrounded && this.stateTime > 30) {
          if (this.hp <= 0) {
            this.state = 'dead';
          } else {
            this.state = 'getup';
            this.stateTime = 0;
          }
        }
        break;

      case 'getup':
        if (this.stateTime > 14) {
          this.state = 'idle';
        }
        break;

      case 'dead':
        break;
    }

    this.computeJoints();
  }

  handleStandardActions(input, opponent) {
    if (this.blockStunTimer > 0) {
      this.isGuarding = true;
      this.state = 'block';
      return;
    }

    this.isGuarding = false;
    this.isCrouching = false;

    if (input.guard) {
      this.isGuarding = true;
      this.isCrouching = Boolean(input.down);
      this.state = 'block';
      this.vx *= 0.5;
      return;
    } else if (this.state === 'block') {
      this.state = 'idle';
    }

    if (input.hop && this.isGrounded) {
      this.isGrounded = false;
      this.vy = -11.5;
      if (input.left) {
        this.vx = -8.5;
      } else if (input.right) {
        this.vx = 8.5;
      } else {
        this.vx = this.facing * 7.5;
      }
      this.state = 'hop';
      this.stateTime = 0;
      this.game.sound.playWhoosh(650);
      this.game.spawnDust(this.x, this.y, 7);
      this.game.updateMoveHUD(this.id, 'TACTICAL HOP');
      return;
    }

    if (input.up && this.isGrounded) {
      this.isGrounded = false;
      this.vy = -16.8;
      this.vx = input.left ? -6.5 : input.right ? 6.5 : 0;
      this.state = 'jump';
      this.stateTime = 0;
      this.game.sound.playWhoosh(580);
      this.game.spawnDust(this.x, this.y, 9);
      this.game.updateMoveHUD(this.id, 'HIGH JUMP');
      return;
    }

    if (input.dash && this.isGrounded) {
      this.state = 'dash';
      this.stateTime = 0;
      this.isDashing = true;
      const dir = input.left ? -1 : input.right ? 1 : this.facing;
      this.vx = dir * 13.5;
      this.game.sound.playWhoosh(720);
      this.game.spawnDust(this.x, this.y, 10);
      this.game.updateMoveHUD(this.id, 'EVASIVE DASH');
      return;
    }

    if (input.down && this.isGrounded) {
      this.isCrouching = true;
      this.state = 'crouch';
      this.vx = 0;

      if (input.lowKick || input.roundhouse) {
        this.startMove(MOVES.sweep);
        return;
      }
      if (input.uppercut || input.jab || input.cross || input.hook) {
        this.startMove(MOVES.uppercut);
        return;
      }
      return;
    }

    if (input.super && this.superMeter >= 100) {
      this.startMove(MOVES.super_strike);
      this.superMeter = 0;
      this.game.sound.playSuper();
      this.game.flashSuper(this);
      return;
    }
    if (input.flyingKnee) {
      this.startMove(MOVES.flying_knee);
      return;
    }
    if (input.roundhouse) {
      this.startMove(MOVES.roundhouse);
      return;
    }
    if (input.hook) {
      this.startMove(MOVES.hook);
      return;
    }
    if (input.uppercut) {
      this.startMove(MOVES.uppercut);
      return;
    }
    if (input.cross) {
      this.startMove(MOVES.cross);
      return;
    }
    if (input.lowKick) {
      this.startMove(MOVES.leg_kick);
      return;
    }
    if (input.jab) {
      this.startMove(MOVES.jab);
      return;
    }

    const walkSpeed = 5.6;
    if (input.left) {
      this.vx = -walkSpeed;
      this.state = 'walk';
    } else if (input.right) {
      this.vx = walkSpeed;
      this.state = 'walk';
    } else {
      this.state = 'idle';
    }
  }

  startMove(move) {
    this.currentMove = move;
    this.state = 'attack';
    this.stateTime = 0;
    this.moveFrame = 0;
    this.hasHitCurrentMove = false;

    if (move.id === 'flying_knee') {
      this.isGrounded = false;
      this.vy = -7.5;
      this.vx = this.facing * 10.5;
      this.game.spawnDust(this.x, this.y, 8);
    } else if (move.id === 'roundhouse') {
      this.vx = this.facing * 4.5;
    } else if (move.id === 'sweep') {
      this.vx = this.facing * 6;
      this.game.spawnDust(this.x, this.y, 6);
    } else if (move.id === 'cross' || move.id === 'hook') {
      this.vx = this.facing * 3.5;
    } else if (move.id === 'super_strike') {
      this.vx = this.facing * 9;
    }

    this.game.sound.playWhoosh(move.whooshPitch);
    this.game.updateMoveHUD(this.id, move.name);
  }

  updateAttack(opponent) {
    this.moveFrame++;
    const move = this.currentMove;

    if (!move) {
      this.state = 'idle';
      return;
    }

    if (this.moveFrame >= move.activeStart && this.moveFrame <= move.activeEnd && !this.hasHitCurrentMove) {
      this.checkHitbox(opponent, move);
    }

    if (move.id === 'super_strike') {
      if (this.moveFrame === 15 || this.moveFrame === 26) {
        this.hasHitCurrentMove = false;
        this.vx = this.facing * 8;
        this.game.sound.playWhoosh(320);
      }
    }

    if (this.moveFrame >= move.totalFrames) {
      this.state = this.isGrounded ? 'idle' : 'jump';
      this.currentMove = null;
      this.hasHitCurrentMove = false;
      this.game.updateMoveHUD(this.id, 'READY');
    }
  }

  checkHitbox(opponent, move) {
    if (opponent.state === 'dead' || this.game.matchState !== 'fighting') return;

    if (!opponent.isGrounded && (move.attackType === 'low' || move.attackType === 'sweep')) {
      return;
    }

    const dx = (opponent.x - this.x) * this.facing;
    const dy = Math.abs(opponent.y - this.y);

    if (dx >= -15 && dx <= move.range && dy < 105) {
      this.hasHitCurrentMove = true;

      const isBlocked = opponent.isGuarding && (move.attackType !== 'sweep' || opponent.isCrouching);

      if (isBlocked) {
        opponent.takeBlock(move, this);
        this.game.sound.playBlock();
        this.game.spawnSpark(opponent.x - (10 * this.facing), opponent.y - 120, '#00e5ff', 8);
        this.game.updateMoveHUD(opponent.id, 'BLOCKED!');
        this.game.queueNetEvent({ type: 'block', x: opponent.x - (10 * this.facing), y: opponent.y - 120, id: opponent.id });
      } else {
        opponent.takeDamage(move, this);
        this.superMeter = Math.min(100, this.superMeter + move.superGain);
        this.comboCount++;
        if (this.comboCount > this.maxCombo) this.maxCombo = this.comboCount;
        this.comboTimer = 75;
        this.game.showCombo(this.id, this.comboCount);

        const isHeavy = move.damage >= 6.5 || move.id === 'super_strike';
        if (isHeavy) {
          this.game.sound.playHitHeavy();
          this.game.shakeScreen(7);
          this.game.spawnSpark(opponent.x, opponent.y - 110, '#ffd600', 16);
          this.game.spawnShockwave(opponent.x, opponent.y - 110);
        } else {
          this.game.sound.playHitLight();
          this.game.shakeScreen(3);
          this.game.spawnSpark(opponent.x, opponent.y - 110, '#ff1744', 10);
        }

        this.game.queueNetEvent({
          type: isHeavy ? 'hit_heavy' : 'hit_light',
          x: opponent.x,
          y: opponent.y - 110,
          attackerId: this.id,
          comboCount: this.comboCount
        });

        this.game.hitFreeze(isHeavy ? 4 : 2);
      }
    }
  }

  takeDamage(move, attacker) {
    if (this.state === 'dead' || this.game.matchState !== 'fighting') return;

    this.hp = Math.max(0, Math.round((this.hp - move.damage) * 10) / 10);
    this.superMeter = Math.min(100, this.superMeter + (move.damage * 1.4));
    this.stateTime = 0;
    this.isGuarding = false;
    this.currentMove = null;

    if (this.hp <= 0) {
      this.hp = 0;
      this.state = 'dead';
      this.vx = attacker.facing * 12;
      this.vy = -9;
      this.isGrounded = false;
      this.game.triggerKO(attacker, this);
      return;
    }

    if (move.attackType === 'sweep' || move.damage >= 8.0 || (move.id === 'super_strike' && attacker.moveFrame >= 26)) {
      this.state = 'knockdown';
      this.vx = attacker.facing * move.knockback.x;
      this.vy = move.knockback.y;
      this.isGrounded = false;
    } else {
      this.state = 'hurt';
      this.hitstunDuration = move.hitstun;
      this.vx = attacker.facing * move.knockback.x;
      this.vy = move.knockback.y;
      if (this.vy < 0) this.isGrounded = false;
    }
  }

  takeBlock(move, attacker) {
    if (this.state === 'dead' || this.game.matchState !== 'fighting') return;

    const chipDamage = 0.5;
    this.hp = Math.max(0, Math.round((this.hp - chipDamage) * 10) / 10);
    this.superMeter = Math.min(100, this.superMeter + 3);
    this.vx = attacker.facing * (move.knockback.x * 0.35);

    if (this.hp <= 0) {
      this.hp = 0;
      this.isGuarding = false;
      this.state = 'dead';
      this.vx = attacker.facing * 10;
      this.vy = -8;
      this.isGrounded = false;
      this.game.triggerKO(attacker, this);
      return;
    }

    this.state = 'block';
    this.blockStunTimer = move.blockstun || 7;
  }

  computeJoints() {
    const j = this.getDefaultJoints();
    const t = this.stateTime;

    if (this.state === 'idle') {
      const bob = Math.sin(t * 0.14) * 5;
      j.pelvis.y += bob;
      j.chest.y += bob;
      j.head.y += bob;
      j.handL.y += bob * 1.2;
      j.handR.y += bob * 0.8;
    } else if (this.state === 'walk') {
      const walkCycle = Math.sin(t * 0.28);
      const bob = Math.abs(walkCycle) * 4;
      j.pelvis.y += bob;
      j.chest.y += bob;
      j.head.y += bob;
      j.kneeL.x += walkCycle * 18;
      j.footL.x += walkCycle * 26;
      j.kneeR.x -= walkCycle * 18;
      j.footR.x -= walkCycle * 26;
    } else if (this.state === 'crouch') {
      j.pelvis.y = -50;
      j.chest.y = -95;
      j.head.y = -130;
      j.kneeL.x = 24; j.kneeL.y = -25;
      j.kneeR.x = -20; j.kneeR.y = -25;
      j.handL.y = -105; j.handR.y = -95;
    } else if (this.state === 'block') {
      if (this.isCrouching) {
        j.pelvis.y = -55;
        j.chest.y = -100;
        j.head.y = -135;
        j.handL.x = 18; j.handL.y = -130;
        j.handR.x = 10; j.handR.y = -125;
      } else {
        j.handL.x = 18; j.handL.y = -165;
        j.handR.x = 10; j.handR.y = -160;
        j.elbowL.x = 12; j.elbowL.y = -130;
        j.elbowR.x = 8; j.elbowR.y = -125;
        j.chest.x = -6;
      }
    } else if (this.state === 'jump' || this.state === 'hop') {
      j.kneeL.y = -62; j.kneeL.x = 18;
      j.kneeR.y = -68; j.kneeR.x = -12;
      j.footL.y = -28; j.footL.x = 6;
      j.footR.y = -35; j.footR.x = -20;
      j.handL.y = -145; j.handR.y = -140;
    } else if (this.state === 'dash') {
      j.chest.x = 16;
      j.head.x = 22;
      j.footL.x = -20;
      j.footR.x = 24;
    } else if (this.state === 'hurt') {
      j.chest.x = -18;
      j.head.x = -30;
      j.head.y = -170;
      j.handL.x = -15; j.handL.y = -110;
      j.handR.x = -5; j.handR.y = -100;
    } else if (this.state === 'knockdown' || this.state === 'dead') {
      const spin = Math.min(1, t / 14);
      j.pelvis.y = -22;
      j.chest.x = -48 * spin; j.chest.y = -28;
      j.head.x = -88 * spin; j.head.y = -32;
      j.kneeL.x = 20; j.kneeL.y = -18;
      j.footL.x = 48; j.footL.y = -10;
      j.kneeR.x = 10; j.kneeR.y = -12;
      j.footR.x = 30; j.footR.y = -6;
      j.handL.x = -30; j.handL.y = -12;
      j.handR.x = -50; j.handR.y = -10;
    } else if (this.state === 'getup') {
      const prog = t / 14;
      j.chest.y = -28 - (112 * prog);
      j.head.y = -32 - (143 * prog);
    } else if (this.state === 'attack' && this.currentMove) {
      this.applyAttackPose(j, this.currentMove, this.moveFrame);
    }

    this.joints = j;
  }

  applyAttackPose(j, move, frame) {
    const p = frame / move.totalFrames;

    switch (move.id) {
      case 'jab':
        if (p < 0.4) {
          j.handL.x = 26 + (p / 0.4) * 65;
          j.handL.y = -138;
          j.chest.x = 8;
        } else {
          j.handL.x = 91 - ((p - 0.4) / 0.6) * 65;
        }
        break;

      case 'cross':
        if (p < 0.45) {
          j.handR.x = 14 + (p / 0.45) * 80;
          j.handR.y = -138;
          j.chest.x = 16;
          j.hipR.x = 18;
        } else {
          j.handR.x = 94 - ((p - 0.45) / 0.55) * 80;
        }
        break;

      case 'hook':
        if (p < 0.5) {
          j.elbowL.x = 38; j.elbowL.y = -138;
          j.handL.x = 70; j.handL.y = -142;
          j.chest.x = 14;
        } else {
          j.handL.x = 70 - ((p - 0.5) / 0.5) * 44;
        }
        break;

      case 'uppercut':
        if (p < 0.45) {
          j.pelvis.y = -75;
          j.handL.x = 38; j.handL.y = -80 - (p / 0.45) * 105;
          j.chest.y = -125 - (p / 0.45) * 25;
        } else {
          j.handL.y = -185 + ((p - 0.45) / 0.55) * 50;
        }
        break;

      case 'leg_kick':
        if (p < 0.5) {
          j.kneeR.x = 38; j.kneeR.y = -40;
          j.footR.x = 80; j.footR.y = -22;
          j.chest.x = -12;
        } else {
          j.footR.x = 80 - ((p - 0.5) / 0.5) * 96;
        }
        break;

      case 'sweep':
        j.pelvis.y = -40;
        j.chest.y = -75;
        j.head.y = -105;
        if (p < 0.55) {
          j.footR.x = -10 + (p / 0.55) * 102;
          j.footR.y = -5;
        } else {
          j.footR.x = 92 - ((p - 0.55) / 0.45) * 102;
        }
        break;

      case 'roundhouse':
        if (p < 0.5) {
          j.chest.x = -15;
          j.hipL.x = 10;
          j.kneeL.x = 42; j.kneeL.y = -120;
          j.footL.x = 96; j.footL.y = -148;
        } else {
          j.footL.x = 96 - ((p - 0.5) / 0.5) * 82;
          j.footL.y = -148 + ((p - 0.5) / 0.5) * 148;
        }
        break;

      case 'air_kick':
        j.chest.x = -10;
        j.kneeL.x = 40; j.kneeL.y = -100;
        j.footL.x = 88; j.footL.y = -95;
        j.kneeR.x = -20; j.kneeR.y = -65;
        j.footR.x = -35; j.footR.y = -40;
        break;

      case 'flying_knee':
        j.kneeL.x = 68; j.kneeL.y = -112;
        j.footL.x = 25; j.footL.y = -55;
        j.handL.x = 40; j.handL.y = -150;
        j.chest.x = 20;
        break;

      case 'super_strike':
        const subPhase = Math.floor(frame / 9) % 3;
        if (subPhase === 0) {
          j.handL.x = 88; j.handL.y = -140;
        } else if (subPhase === 1) {
          j.handR.x = 96; j.handR.y = -135;
        } else {
          j.footL.x = 94; j.footL.y = -150;
        }
        break;
    }
  }

  draw(ctx) {
    ctx.save();
    ctx.translate(this.x, this.y);

    const f = this.facing;
    const j = this.joints;

    ctx.save();
    ctx.fillStyle = 'rgba(0, 0, 0, 0.45)';
    ctx.beginPath();
    const shadowScale = Math.max(0.4, 1 - (this.groundY - this.y) / 300);
    ctx.ellipse(0, this.groundY - this.y + 4, 34 * shadowScale, 8 * shadowScale, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    ctx.shadowBlur = 12;
    ctx.shadowColor = this.color;
    ctx.strokeStyle = this.color;
    ctx.fillStyle = this.color;
    ctx.lineWidth = 5.5;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.save();
    ctx.globalAlpha = 0.65;
    this.drawLine(ctx, j.pelvis.x * f, j.pelvis.y, j.hipR.x * f, j.hipR.y);
    this.drawLine(ctx, j.hipR.x * f, j.hipR.y, j.kneeR.x * f, j.kneeR.y);
    this.drawLine(ctx, j.kneeR.x * f, j.kneeR.y, j.footR.x * f, j.footR.y);
    this.drawLine(ctx, j.chest.x * f, j.chest.y, j.shoulderR.x * f, j.shoulderR.y);
    this.drawLine(ctx, j.shoulderR.x * f, j.shoulderR.y, j.elbowR.x * f, j.elbowR.y);
    this.drawLine(ctx, j.elbowR.x * f, j.elbowR.y, j.handR.x * f, j.handR.y);
    ctx.restore();

    this.drawLine(ctx, j.pelvis.x * f, j.pelvis.y, j.chest.x * f, j.chest.y);

    ctx.beginPath();
    ctx.arc(j.head.x * f, j.head.y, 18, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = '#ffffff';
    ctx.fillRect((j.head.x + 4) * f - 6, j.head.y - 4, 12, 5);

    this.drawLine(ctx, j.pelvis.x * f, j.pelvis.y, j.hipL.x * f, j.hipL.y);
    this.drawLine(ctx, j.hipL.x * f, j.hipL.y, j.kneeL.x * f, j.kneeL.y);
    this.drawLine(ctx, j.kneeL.x * f, j.kneeL.y, j.footL.x * f, j.footL.y);
    this.drawLine(ctx, j.chest.x * f, j.chest.y, j.shoulderL.x * f, j.shoulderL.y);
    this.drawLine(ctx, j.shoulderL.x * f, j.shoulderL.y, j.elbowL.x * f, j.elbowL.y);
    this.drawLine(ctx, j.elbowL.x * f, j.elbowL.y, j.handL.x * f, j.handL.y);

    ctx.beginPath();
    ctx.arc(j.handL.x * f, j.handL.y, 6, 0, Math.PI * 2);
    ctx.arc(j.handR.x * f, j.handR.y, 6, 0, Math.PI * 2);
    ctx.fill();

    if (this.isGuarding) {
      ctx.beginPath();
      ctx.arc(15 * f, this.isCrouching ? -85 : -115, 46, -Math.PI / 2, Math.PI / 2, f < 0);
      ctx.strokeStyle = 'rgba(0, 229, 255, 0.75)';
      ctx.lineWidth = 4;
      ctx.stroke();
    }

    ctx.restore();
  }

  drawLine(ctx, x1, y1, x2, y2) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
  }
}

// --- Intelligent Tactical AI Controller ---
class AIController {
  constructor(fighter, opponent, difficulty = 'normal') {
    this.fighter = fighter;
    this.opponent = opponent;
    this.difficulty = difficulty;

    this.currentBehavior = 'idle';
    this.behaviorTimer = 0;
    this.blockCooldown = 0;
    this.comboQueue = [];
    this.comboDelay = 0;
  }

  setDifficulty(level) {
    this.difficulty = level;
  }

  reset() {
    this.currentBehavior = 'idle';
    this.behaviorTimer = 0;
    this.blockCooldown = 0;
    this.comboQueue = [];
    this.comboDelay = 0;
  }

  createEmptyInput() {
    return {
      left: false, right: false, up: false, down: false, hop: false,
      jab: false, cross: false, hook: false, uppercut: false,
      lowKick: false, roundhouse: false, flyingKnee: false,
      guard: false, dash: false, super: false
    };
  }

  update() {
    const input = this.createEmptyInput();
    const f = this.fighter;
    const opp = this.opponent;

    if (f.state === 'dead' || opp.state === 'dead') return input;

    if (this.blockCooldown > 0) this.blockCooldown--;
    if (this.behaviorTimer > 0) this.behaviorTimer--;

    const dx = opp.x - f.x;
    const dist = Math.abs(dx);
    const dirToOpp = dx > 0 ? 'right' : 'left';
    const dirAway = dx > 0 ? 'left' : 'right';

    const blockProb = this.difficulty === 'hard' ? 0.75 : this.difficulty === 'normal' ? 0.45 : 0.2;
    const aggression = this.difficulty === 'hard' ? 0.88 : this.difficulty === 'normal' ? 0.68 : 0.42;

    if (this.comboQueue.length > 0) {
      if (f.state === 'idle' || f.state === 'walk') {
        if (this.comboDelay > 0) {
          this.comboDelay--;
          input[dirToOpp] = dist > 75;
          return input;
        }
        const nextMove = this.comboQueue.shift();
        if (nextMove === 'sweep') {
          input.down = true;
          input.lowKick = true;
        } else {
          input[nextMove] = true;
        }
        this.comboDelay = 3;
        return input;
      }
      return input;
    }

    if (this.currentBehavior === 'block' || this.currentBehavior === 'crouch_block') {
      if (this.behaviorTimer > 0 && opp.state === 'attack') {
        input.guard = true;
        if (this.currentBehavior === 'crouch_block') input.down = true;
        return input;
      } else {
        this.currentBehavior = 'idle';
        this.blockCooldown = 35;
        if (dist < 105) {
          input.jab = true;
          this.comboQueue = ['cross'];
          return input;
        }
      }
    }

    if (opp.state === 'attack' && dist < 130 && this.blockCooldown === 0 && f.state !== 'attack') {
      if (Math.random() < blockProb) {
        if (opp.currentMove && (opp.currentMove.attackType === 'sweep' || opp.currentMove.attackType === 'low')) {
          if (Math.random() < 0.5) {
            input.hop = true;
            input[dirToOpp] = true;
            this.blockCooldown = 30;
            return input;
          } else {
            this.currentBehavior = 'crouch_block';
            this.behaviorTimer = 14;
            input.guard = true;
            input.down = true;
            return input;
          }
        } else {
          this.currentBehavior = 'block';
          this.behaviorTimer = 12;
          input.guard = true;
          return input;
        }
      } else {
        this.blockCooldown = 22;
      }
    }

    if (f.superMeter >= 100 && dist < 120 && f.isGrounded && f.state !== 'attack') {
      if (Math.random() < 0.65) {
        input.super = true;
        return input;
      }
    }

    if (this.behaviorTimer > 0 && dist > 95 && this.currentBehavior === 'approach') {
      input[dirToOpp] = true;
      return input;
    }
    if (this.behaviorTimer > 0 && this.currentBehavior === 'retreat') {
      input[dirAway] = true;
      return input;
    }

    if (dist > 220) {
      const r = Math.random();
      if (r < 0.22) {
        input.dash = true;
        input[dirToOpp] = true;
      } else if (r < 0.45) {
        input.hop = true;
        input[dirToOpp] = true;
      } else {
        this.currentBehavior = 'approach';
        this.behaviorTimer = 18;
        input[dirToOpp] = true;
      }
    } else if (dist > 100) {
      const r = Math.random();
      if (r < 0.25 * aggression) {
        input.flyingKnee = true;
      } else if (r < 0.48 * aggression) {
        input.roundhouse = true;
      } else if (r < 0.65 * aggression) {
        input.hop = true;
        input[dirToOpp] = true;
        this.comboQueue = ['lowKick'];
      } else {
        this.currentBehavior = 'approach';
        this.behaviorTimer = 12;
        input[dirToOpp] = true;
      }
    } else {
      if (Math.random() < aggression) {
        const roll = Math.random();
        if (opp.isGuarding && !opp.isCrouching && roll < 0.55) {
          input.down = true;
          input.lowKick = true;
        } else if (roll < 0.28) {
          input.jab = true;
          this.comboQueue = this.difficulty === 'easy' ? ['cross'] : ['cross', 'hook'];
        } else if (roll < 0.50) {
          input.lowKick = true;
          if (this.difficulty !== 'easy') this.comboQueue = ['roundhouse'];
        } else if (roll < 0.68) {
          input.uppercut = true;
        } else if (roll < 0.84) {
          input.down = true;
          input.lowKick = true;
        } else {
          input.up = true;
          input[dirToOpp] = true;
          this.comboQueue = ['roundhouse'];
        }
        this.behaviorTimer = 10;
      } else {
        if (Math.random() < 0.4) {
          input.hop = true;
          input[dirAway] = true;
        } else {
          this.currentBehavior = 'retreat';
          this.behaviorTimer = 10;
          input[dirAway] = true;
        }
      }
    }

    return input;
  }
}

// --- Main Game Engine ---
class StickmanGame {
  constructor() {
    this.canvas = document.getElementById('gameCanvas');
    this.ctx = this.canvas.getContext('2d');
    this.sound = new SoundEngine();

    // Game Modes: 'ai' | 'online' (2-PC WebRTC) | 'local2p' (Same-PC PvP)
    this.gameMode = 'ai';
    this.net = new NetworkManager(this);
    this.remoteP2Input = null;
    this.pendingNetEvents = [];

    // Fighters
    this.p1 = new Fighter(this, 'p1', 'SHADOW', 360, '#00e5ff', 1, false);
    this.p2 = new Fighter(this, 'p2', 'VIPER', 920, '#ff1744', -1, true);
    this.ai = new AIController(this.p2, this.p1, 'normal');

    // Match Format & State — Starts on Home Menu ('menu'), NOT in a fight!
    this.roundsToWin = 1;
    this.roundNumber = 1;
    this.roundTime = 99;
    this.timerInterval = null;
    this.roundTransitionTimeout = null;
    this.matchState = 'menu'; // 'menu', 'countdown', 'fighting', 'round_over', 'match_over'
    this.freezeFrames = 0;
    this.screenShake = 0;

    // Visual FX Systems
    this.particles = [];
    this.shockwaves = [];

    // Input Controller
    this.keyState = {};

    this.bindEvents();
    this.loop = this.loop.bind(this);
    requestAnimationFrame(this.loop);
  }

  bindEvents() {
    window.addEventListener('keydown', (e) => {
      if (['INPUT', 'TEXTAREA'].includes(document.activeElement && document.activeElement.tagName)) {
        return;
      }
      this.sound.init();
      this.keyState[e.code] = true;

      if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code) && this.matchState === 'fighting') {
        e.preventDefault();
      }

      if (e.code === 'Enter' && this.matchState === 'match_over') {
        this.requestRematch();
      }
    });

    window.addEventListener('keyup', (e) => {
      this.keyState[e.code] = false;
    });

    // --- Home Page Menu Navigation ---
    const mainMenuPanel = document.getElementById('mainMenuPanel');
    const startGameSubPanel = document.getElementById('startGameSubPanel');

    document.getElementById('btnMenuStartGame').addEventListener('click', () => {
      this.sound.init();
      mainMenuPanel.style.display = 'none';
      startGameSubPanel.style.display = 'flex';
    });

    document.getElementById('btnBackToMain').addEventListener('click', () => {
      startGameSubPanel.style.display = 'none';
      mainMenuPanel.style.display = 'flex';
    });

    // Start Game Option 1: Offline (AI)
    document.getElementById('btnStartOfflineAI').addEventListener('click', () => {
      this.sound.init();
      this.enterArenaScreen('ai');
      this.startMatch();
    });

    // Start Game Option 2: Offline (PvP)
    document.getElementById('btnStartOfflinePvP').addEventListener('click', () => {
      this.sound.init();
      this.enterArenaScreen('local2p');
      this.startMatch();
    });

    // Start Game Option 3: Multiplayer (2-PC)
    document.getElementById('btnStartMultiplayer').addEventListener('click', () => {
      this.sound.init();
      this.gameMode = 'online';
      document.getElementById('multiplayerModal').classList.add('open');
    });

    // Return to Main Menu (from Header or Game Over screen)
    document.getElementById('btnMainMenu').addEventListener('click', () => {
      this.returnToHomeMenu();
    });
    document.getElementById('btnGameOverMenu').addEventListener('click', () => {
      this.returnToHomeMenu();
    });

    // Controls Modal (from Home Page or In-Game Header)
    const controlsModal = document.getElementById('controlsModal');
    document.getElementById('btnMenuControls').addEventListener('click', () => {
      controlsModal.classList.add('open');
    });
    document.getElementById('btnControlsHeader').addEventListener('click', () => {
      controlsModal.classList.add('open');
    });
    document.getElementById('btnCloseControlsModal').addEventListener('click', () => {
      controlsModal.classList.remove('open');
    });

    // Credits Modal (from Home Page)
    const creditsModal = document.getElementById('creditsModal');
    document.getElementById('btnMenuCredits').addEventListener('click', () => {
      creditsModal.classList.add('open');
    });
    document.getElementById('btnCloseCreditsModal').addEventListener('click', () => {
      creditsModal.classList.remove('open');
    });

    // Multiplayer Lobby Modal Controls
    const mpModal = document.getElementById('multiplayerModal');
    document.getElementById('btnNetLobby').addEventListener('click', () => {
      mpModal.classList.add('open');
    });
    document.getElementById('btnCloseMpModal').addEventListener('click', () => {
      mpModal.classList.remove('open');
    });

    // Multiplayer Tabs
    document.getElementById('tabRoomCode').addEventListener('click', () => {
      document.getElementById('tabRoomCode').classList.add('active');
      document.getElementById('tabDirectLan').classList.remove('active');
      document.getElementById('sectionRoomCode').style.display = 'block';
      document.getElementById('sectionDirectLan').style.display = 'none';
    });
    document.getElementById('tabDirectLan').addEventListener('click', () => {
      document.getElementById('tabDirectLan').classList.add('active');
      document.getElementById('tabRoomCode').classList.remove('active');
      document.getElementById('sectionDirectLan').style.display = 'block';
      document.getElementById('sectionRoomCode').style.display = 'none';
    });

    // Room Code Buttons
    document.getElementById('btnCreateRoom').addEventListener('click', () => {
      this.net.createRoom();
    });
    document.getElementById('btnCopyRoomCode').addEventListener('click', () => {
      if (this.net.roomCode && navigator.clipboard) {
        navigator.clipboard.writeText(this.net.roomCode);
        document.getElementById('btnCopyRoomCode').textContent = '✅ Copied!';
        setTimeout(() => {
          document.getElementById('btnCopyRoomCode').textContent = '📋 Copy';
        }, 1500);
      }
    });
    document.getElementById('btnJoinRoom').addEventListener('click', () => {
      const code = document.getElementById('joinRoomInput').value;
      this.net.joinRoom(code);
    });

    // Offline LAN Manual SDP Buttons
    document.getElementById('btnLanCreateOffer').addEventListener('click', () => {
      this.net.createLanOffer();
    });
    document.getElementById('btnLanCreateAnswer').addEventListener('click', () => {
      const offer = document.getElementById('lanOfferIn').value;
      this.net.createLanAnswer(offer);
    });
    document.getElementById('btnLanAcceptAnswer').addEventListener('click', () => {
      const answer = document.getElementById('lanAnswerIn').value;
      this.net.acceptLanAnswer(answer);
    });

    // Header & Match Buttons
    document.getElementById('btnSound').addEventListener('click', () => {
      const on = this.sound.toggle();
      document.getElementById('btnSound').textContent = on ? '🔊' : '🔇';
    });

    document.getElementById('btnRestart').addEventListener('click', () => {
      this.requestRematch();
    });

    document.getElementById('btnPlayAgain').addEventListener('click', () => {
      this.requestRematch();
    });

    document.getElementById('aiDifficulty').addEventListener('change', (e) => {
      this.ai.setDifficulty(e.target.value);
    });

    document.getElementById('matchFormat').addEventListener('change', (e) => {
      this.roundsToWin = parseInt(e.target.value, 10) || 1;
      this.requestRematch();
    });
  }

  enterArenaScreen(mode) {
    this.gameMode = mode;
    document.getElementById('homeMenuOverlay').style.display = 'none';
    document.getElementById('gameHeader').style.display = 'flex';
    document.getElementById('matchHud').style.display = 'grid';

    const aiLevelWrap = document.getElementById('aiLevelWrap');
    const btnNetLobby = document.getElementById('btnNetLobby');
    const p1Badge = document.getElementById('p1RoleBadge');
    const p2Badge = document.getElementById('p2RoleBadge');

    if (mode === 'ai') {
      this.net.disconnect();
      this.p2.isAI = true;
      aiLevelWrap.style.display = 'flex';
      btnNetLobby.style.display = 'none';
      p1Badge.textContent = 'P1 HUMAN';
      p2Badge.textContent = 'AI';
    } else if (mode === 'local2p') {
      this.net.disconnect();
      this.p2.isAI = false;
      aiLevelWrap.style.display = 'none';
      btnNetLobby.style.display = 'none';
      p1Badge.textContent = 'P1 HUMAN';
      p2Badge.textContent = 'P2 HUMAN';
    } else if (mode === 'online') {
      this.p2.isAI = false;
      aiLevelWrap.style.display = 'none';
      btnNetLobby.style.display = 'flex';
      p1Badge.textContent = 'PC 1 (HOST)';
      p2Badge.textContent = 'PC 2 (GUEST)';
    }
  }

  returnToHomeMenu() {
    clearTimeout(this.roundTransitionTimeout);
    clearInterval(this.timerInterval);
    this.net.disconnect();
    this.hideAnnouncer();
    this.hideGameOverModal();

    this.matchState = 'menu';
    this.p1.resetRound(360, 1);
    this.p2.resetRound(920, -1);

    document.getElementById('gameHeader').style.display = 'none';
    document.getElementById('matchHud').style.display = 'none';
    document.getElementById('homeMenuOverlay').style.display = 'flex';
    document.getElementById('mainMenuPanel').style.display = 'flex';
    document.getElementById('startGameSubPanel').style.display = 'none';
  }

  onNetworkStatusChange(isConnected, labelText) {
    const dot = document.getElementById('netStatusDot');
    const txt = document.getElementById('netStatusText');
    if (dot) dot.classList.toggle('connected', isConnected);
    if (txt) txt.textContent = labelText;
  }

  setMpBanner(msg) {
    const el = document.getElementById('mpStatusBanner');
    if (el) el.textContent = msg;
  }

  queueNetEvent(evt) {
    if (this.gameMode === 'online' && this.net.role === 'host') {
      this.pendingNetEvents.push(evt);
    }
  }

  onNetworkData(data) {
    if (!data) return;

    if (this.net.role === 'host') {
      if (data.type === 'guest_input') {
        this.remoteP2Input = data.input;
      } else if (data.type === 'rematch_request') {
        this.startMatch();
      }
      return;
    }

    if (this.net.role === 'guest' && data.type === 'host_state') {
      this.p1.applySnapshot(data.p1);
      this.p2.applySnapshot(data.p2);
      this.roundNumber = data.roundNumber;
      this.roundTime = data.roundTime;
      this.matchState = data.matchState;

      document.getElementById('timerCount').textContent = this.roundTime;
      document.getElementById('roundNumberTag').textContent = `ROUND ${this.roundNumber}`;
      this.updateRoundsWonUI();

      if (Array.isArray(data.events)) {
        for (const ev of data.events) {
          if (ev.type === 'hit_heavy') {
            this.sound.playHitHeavy();
            this.shakeScreen(7);
            this.spawnSpark(ev.x, ev.y, '#ffd600', 16);
            this.spawnShockwave(ev.x, ev.y);
            this.showCombo(ev.attackerId, ev.comboCount);
          } else if (ev.type === 'hit_light') {
            this.sound.playHitLight();
            this.shakeScreen(3);
            this.spawnSpark(ev.x, ev.y, '#ff1744', 10);
            this.showCombo(ev.attackerId, ev.comboCount);
          } else if (ev.type === 'block') {
            this.sound.playBlock();
            this.spawnSpark(ev.x, ev.y, '#00e5ff', 8);
            this.updateMoveHUD(ev.id, 'BLOCKED!');
          } else if (ev.type === 'announcer') {
            if (ev.hide) {
              this.hideAnnouncer();
            } else {
              this.showAnnouncer(ev.title, ev.sub);
              if (ev.roundResultSound) {
                if (ev.winnerId === 'p2') this.sound.playWinSound();
                else if (ev.winnerId === 'p1') this.sound.playLoseSound();
              }
            }
          } else if (ev.type === 'gameover') {
            if (ev.hide) {
              this.hideGameOverModal();
            } else {
              const winner = ev.winnerId === 'p1' ? this.p1 : this.p2;
              this.showGameOverModal(winner, ev.reasonText);
            }
          }
        }
      }
    }
  }

  requestRematch() {
    if (this.gameMode === 'online' && this.net.connected && this.net.role === 'guest') {
      this.net.send({ type: 'rematch_request' });
      return;
    }
    this.startMatch();
  }

  gatherPrimaryInput() {
    const allowArrows = this.gameMode !== 'local2p';
    return {
      left: Boolean(this.keyState['KeyA'] || (allowArrows && this.keyState['ArrowLeft'])),
      right: Boolean(this.keyState['KeyD'] || (allowArrows && this.keyState['ArrowRight'])),
      up: Boolean(this.keyState['KeyW'] || (allowArrows && this.keyState['ArrowUp'])),
      down: Boolean(this.keyState['KeyS'] || (allowArrows && this.keyState['ArrowDown'])),
      hop: Boolean(this.keyState['KeyQ'] || this.keyState['AltLeft']),
      dash: Boolean(this.keyState['Space']),
      jab: Boolean(this.keyState['KeyJ']),
      cross: Boolean(this.keyState['KeyU']),
      hook: Boolean(this.keyState['KeyH']),
      uppercut: Boolean(this.keyState['KeyY']),
      lowKick: Boolean(this.keyState['KeyK']),
      roundhouse: Boolean(this.keyState['KeyL']),
      flyingKnee: Boolean(this.keyState['KeyO']),
      guard: Boolean(this.keyState['KeyI']),
      super: Boolean(this.keyState['KeyP'])
    };
  }

  gatherLocalP2Input() {
    return {
      left: Boolean(this.keyState['ArrowLeft']),
      right: Boolean(this.keyState['ArrowRight']),
      up: Boolean(this.keyState['ArrowUp']),
      down: Boolean(this.keyState['ArrowDown']),
      hop: Boolean(this.keyState['ShiftRight'] || this.keyState['ShiftLeft']),
      dash: Boolean(this.keyState['Enter']),
      jab: Boolean(this.keyState['Numpad1'] || this.keyState['Comma']),
      cross: Boolean(this.keyState['Numpad4'] || this.keyState['Period']),
      hook: Boolean(this.keyState['Numpad5'] || this.keyState['Slash']),
      uppercut: Boolean(this.keyState['Numpad6'] || this.keyState['Semicolon']),
      lowKick: Boolean(this.keyState['Numpad2'] || this.keyState['BracketLeft']),
      roundhouse: Boolean(this.keyState['Numpad3'] || this.keyState['BracketRight']),
      flyingKnee: Boolean(this.keyState['Numpad7'] || this.keyState['Minus']),
      guard: Boolean(this.keyState['Numpad0'] || this.keyState['Quote']),
      super: Boolean(this.keyState['Numpad9'] || this.keyState['Backslash'])
    };
  }

  startMatch() {
    clearTimeout(this.roundTransitionTimeout);
    clearInterval(this.timerInterval);
    this.hideGameOverModal();
    this.queueNetEvent({ type: 'gameover', hide: true });

    this.p1.roundsWon = 0;
    this.p2.roundsWon = 0;
    this.p1.superMeter = 0;
    this.p2.superMeter = 0;
    this.p1.maxCombo = 0;
    this.p2.maxCombo = 0;

    this.updateRoundsWonUI();
    this.startRound(1);
  }

  startRound(num) {
    clearTimeout(this.roundTransitionTimeout);
    clearInterval(this.timerInterval);
    this.hideGameOverModal();

    this.roundNumber = num;
    this.roundTime = 99;
    this.matchState = 'countdown';
    this.p1.resetRound(360, 1);
    this.p2.resetRound(920, -1);
    this.ai.reset();
    this.updateHUD();

    document.getElementById('timerCount').textContent = this.roundTime;
    document.getElementById('roundNumberTag').textContent = `ROUND ${this.roundNumber}`;
    this.showAnnouncer(`ROUND ${this.roundNumber}`, 'FIGHT!');
    this.queueNetEvent({ type: 'announcer', title: `ROUND ${this.roundNumber}`, sub: 'FIGHT!' });
    this.sound.playGong();

    this.roundTransitionTimeout = setTimeout(() => {
      if (this.matchState === 'menu') return;
      this.matchState = 'fighting';
      this.hideAnnouncer();
      this.queueNetEvent({ type: 'announcer', hide: true });
      this.startTimer();
    }, 700);
  }

  startTimer() {
    clearInterval(this.timerInterval);
    this.timerInterval = setInterval(() => {
      if (this.matchState === 'fighting') {
        this.roundTime--;
        document.getElementById('timerCount').textContent = this.roundTime;
        if (this.roundTime <= 0) {
          this.endRoundByTimeout();
        }
      }
    }, 1000);
  }

  triggerKO(winner, loser) {
    if (this.matchState !== 'fighting') return;

    this.matchState = 'round_over';
    clearInterval(this.timerInterval);
    clearTimeout(this.roundTransitionTimeout);

    this.sound.playKO();
    this.shakeScreen(12);
    this.spawnShockwave(loser.x, loser.y - 90);

    winner.roundsWon++;
    this.updateRoundsWonUI();
    this.updateHUD();

    if (winner.roundsWon >= this.roundsToWin) {
      this.showAnnouncer('K.O.!', `${winner.name} WINS!`);
      this.queueNetEvent({ type: 'announcer', title: 'K.O.!', sub: `${winner.name} WINS!` });
      this.roundTransitionTimeout = setTimeout(() => {
        if (this.matchState === 'menu') return;
        this.hideAnnouncer();
        this.queueNetEvent({ type: 'announcer', hide: true });
        this.showGameOverModal(winner, 'Knockout Victory!');
        this.queueNetEvent({ type: 'gameover', winnerId: winner.id, reasonText: 'Knockout Victory!' });
      }, 1500);
    } else {
      if (this.didLocalPlayerWin(winner)) {
        this.sound.playWinSound();
      } else if (this.didLocalPlayerLose(winner)) {
        this.sound.playLoseSound();
      }
      this.showAnnouncer('K.O.!', `${winner.name} TAKES ROUND ${this.roundNumber}!`);
      this.queueNetEvent({ type: 'announcer', title: 'K.O.!', sub: `${winner.name} TAKES ROUND ${this.roundNumber}!`, roundResultSound: true, winnerId: winner.id });
      this.roundTransitionTimeout = setTimeout(() => {
        if (this.matchState === 'menu') return;
        this.startRound(this.roundNumber + 1);
      }, 2200);
    }
  }

  endRoundByTimeout() {
    if (this.matchState !== 'fighting') return;

    this.matchState = 'round_over';
    clearInterval(this.timerInterval);
    clearTimeout(this.roundTransitionTimeout);

    let winner = null;
    if (this.p1.hp > this.p2.hp) winner = this.p1;
    else if (this.p2.hp > this.p1.hp) winner = this.p2;

    if (winner) {
      winner.roundsWon++;
      this.updateRoundsWonUI();
      if (winner.roundsWon >= this.roundsToWin) {
        this.showAnnouncer('TIME OVER', `${winner.name} WINS!`);
        this.queueNetEvent({ type: 'announcer', title: 'TIME OVER', sub: `${winner.name} WINS!` });
        this.roundTransitionTimeout = setTimeout(() => {
          if (this.matchState === 'menu') return;
          this.hideAnnouncer();
          this.showGameOverModal(winner, 'Time Decision Victory');
          this.queueNetEvent({ type: 'gameover', winnerId: winner.id, reasonText: 'Time Decision Victory' });
        }, 1500);
        return;
      } else {
        this.showAnnouncer('TIME OVER', `${winner.name} TAKES ROUND ${this.roundNumber}!`);
      }
    } else {
      this.showAnnouncer('DRAW', 'EQUAL HEALTH');
    }

    this.roundTransitionTimeout = setTimeout(() => {
      if (this.matchState === 'menu') return;
      this.startRound(this.roundNumber + 1);
    }, 2200);
  }

  didLocalPlayerLose(winner) {
    if (!winner) return false;
    if (this.gameMode === 'ai') {
      return winner.id === 'p2'; // Human P1 lost to AI P2
    }
    if (this.gameMode === 'online' && this.net.connected) {
      if (this.net.role === 'host') return winner.id === 'p2';
      if (this.net.role === 'guest') return winner.id === 'p1';
    }
    return winner.id === 'p2';
  }

  didLocalPlayerWin(winner) {
    if (!winner) return false;
    if (this.gameMode === 'ai') {
      return winner.id === 'p1'; // Human P1 defeated AI P2
    }
    if (this.gameMode === 'online' && this.net.connected) {
      if (this.net.role === 'host') return winner.id === 'p1';
      if (this.net.role === 'guest') return winner.id === 'p2';
    }
    if (this.gameMode === 'local2p') {
      return true; // A human player won the round in Offline PvP
    }
    return winner.id === 'p1';
  }

  showGameOverModal(winner, reasonText) {
    this.matchState = 'match_over';
    const isP1Winner = winner.id === 'p1';
    const playerLost = this.didLocalPlayerLose(winner);
    const playerWon = this.didLocalPlayerWin(winner);

    if (playerWon) {
      this.sound.playWinSound();
    } else if (playerLost) {
      this.sound.playLoseSound();
    }

    document.getElementById('goBadge').textContent = playerLost
      ? '💀 GAME OVER — YOU LOST!'
      : '🏆 GAME OVER — VICTORY!';
    const titleEl = document.getElementById('goWinnerTitle');
    titleEl.textContent = `${winner.name} WINS!`;
    titleEl.style.color = isP1Winner ? '#00e5ff' : '#ff1744';

    document.getElementById('goSubtitle').textContent = reasonText;
    document.getElementById('goStatHp').textContent = `${Math.round(winner.hp)}%`;
    document.getElementById('goStatScore').textContent = `${this.p1.roundsWon} - ${this.p2.roundsWon}`;
    const bestCombo = Math.max(this.p1.maxCombo, this.p2.maxCombo, 1);
    document.getElementById('goStatCombo').textContent = `${bestCombo} Hits`;

    document.getElementById('gameOverOverlay').classList.add('show');
  }

  hideGameOverModal() {
    document.getElementById('gameOverOverlay').classList.remove('show');
  }

  showAnnouncer(title, sub) {
    const el = document.getElementById('announcerOverlay');
    document.getElementById('announcerTitle').textContent = title;
    document.getElementById('announcerSub').textContent = sub;
    el.classList.add('show');
  }

  hideAnnouncer() {
    document.getElementById('announcerOverlay').classList.remove('show');
  }

  showCombo(fighterId, count) {
    if (count <= 1) return;
    const banner = document.getElementById(`${fighterId}ComboBanner`);
    banner.querySelector('.combo-count').textContent = count;
    banner.classList.add('show');
    clearTimeout(banner.hideTimeout);
    banner.hideTimeout = setTimeout(() => {
      banner.classList.remove('show');
    }, 1200);
  }

  updateMoveHUD(fighterId, moveName) {
    const el = document.getElementById(`${fighterId}MoveTag`);
    if (!el) return;
    el.textContent = moveName;
    el.classList.add('active');
    clearTimeout(el.clearTimer);
    el.clearTimer = setTimeout(() => {
      el.classList.remove('active');
    }, 600);
  }

  updateHUD() {
    const p1Hp = Math.max(0, this.p1.hp);
    document.getElementById('p1HpFill').style.width = `${p1Hp}%`;
    document.getElementById('p1HpChip').style.width = `${this.p1.displayHp}%`;
    document.getElementById('p1HpVal').textContent = `${Math.ceil(p1Hp)}%`;

    const p1Super = Math.round(this.p1.superMeter);
    const p1SuperFill = document.getElementById('p1SuperFill');
    p1SuperFill.style.width = `${p1Super}%`;
    p1SuperFill.classList.toggle('maxed', p1Super >= 100);
    document.getElementById('p1SuperLabel').textContent = p1Super >= 100 ? 'SUPER READY! (P)' : `SUPER ${p1Super}%`;

    const p2Hp = Math.max(0, this.p2.hp);
    document.getElementById('p2HpFill').style.width = `${p2Hp}%`;
    document.getElementById('p2HpChip').style.width = `${this.p2.displayHp}%`;
    document.getElementById('p2HpVal').textContent = `${Math.ceil(p2Hp)}%`;

    const p2Super = Math.round(this.p2.superMeter);
    const p2SuperFill = document.getElementById('p2SuperFill');
    p2SuperFill.style.width = `${p2Super}%`;
    p2SuperFill.classList.toggle('maxed', p2Super >= 100);
    document.getElementById('p2SuperLabel').textContent = p2Super >= 100 ? 'SUPER READY!' : `SUPER ${p2Super}%`;
  }

  updateRoundsWonUI() {
    const p1Dots = document.getElementById('p1Rounds').children;
    const p2Dots = document.getElementById('p2Rounds').children;
    for (let i = 0; i < 2; i++) {
      p1Dots[i].classList.toggle('won', i < this.p1.roundsWon);
      p2Dots[i].classList.toggle('won', i < this.p2.roundsWon);
    }
  }

  hitFreeze(frames) {
    this.freezeFrames = frames;
  }

  shakeScreen(amt) {
    this.screenShake = amt;
  }

  flashSuper(fighter) {
    this.screenShake = 10;
    this.spawnShockwave(fighter.x, fighter.y - 120);
  }

  spawnSpark(x, y, color = '#ffd600', count = 12) {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = 3 + Math.random() * 8;
      this.particles.push({
        x, y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        life: 16 + Math.random() * 12,
        color,
        size: 3 + Math.random() * 3
      });
    }
  }

  spawnDust(x, y, count = 8) {
    for (let i = 0; i < count; i++) {
      this.particles.push({
        x: x + (Math.random() - 0.5) * 30,
        y: y - 5,
        vx: (Math.random() - 0.5) * 4,
        vy: -1 - Math.random() * 2.5,
        life: 14 + Math.random() * 10,
        color: 'rgba(255, 255, 255, 0.45)',
        size: 4 + Math.random() * 4
      });
    }
  }

  spawnShockwave(x, y) {
    this.shockwaves.push({
      x, y, radius: 10, maxRadius: 95, alpha: 0.9
    });
  }

  updateFX() {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.vy += 0.2;
      p.life--;
      if (p.life <= 0) {
        this.particles.splice(i, 1);
      }
    }

    for (let i = this.shockwaves.length - 1; i >= 0; i--) {
      const s = this.shockwaves[i];
      s.radius += 5.5;
      s.alpha *= 0.88;
      if (s.alpha <= 0.05 || s.radius >= s.maxRadius) {
        this.shockwaves.splice(i, 1);
      }
    }

    if (this.screenShake > 0) {
      this.screenShake *= 0.85;
      if (this.screenShake < 0.2) this.screenShake = 0;
    }
  }

  drawArena() {
    const ctx = this.ctx;
    const w = this.canvas.width;
    const h = this.canvas.height;

    const bgGrad = ctx.createLinearGradient(0, 0, 0, h);
    bgGrad.addColorStop(0, '#0a0e17');
    bgGrad.addColorStop(0.75, '#121824');
    bgGrad.addColorStop(1, '#06080d');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, w, h);

    ctx.strokeStyle = 'rgba(255, 255, 255, 0.04)';
    ctx.lineWidth = 2;
    for (let x = 0; x < w; x += 80) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, 560);
      ctx.stroke();
    }
    for (let y = 80; y < 560; y += 80) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }

    ctx.fillStyle = '#0f1420';
    ctx.fillRect(0, 560, w, h - 560);

    const glowGrad = ctx.createLinearGradient(0, 558, w, 558);
    glowGrad.addColorStop(0, '#00e5ff');
    glowGrad.addColorStop(0.5, '#ffffff');
    glowGrad.addColorStop(1, '#ff1744');
    ctx.fillStyle = glowGrad;
    ctx.fillRect(0, 558, w, 4);

    ctx.strokeStyle = 'rgba(255, 255, 255, 0.07)';
    ctx.lineWidth = 1.5;
    for (let x = -200; x < w + 200; x += 100) {
      ctx.beginPath();
      ctx.moveTo(x, 560);
      ctx.lineTo(x + (x - w / 2) * 0.45, h);
      ctx.stroke();
    }
  }

  drawFX() {
    const ctx = this.ctx;

    for (const s of this.shockwaves) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
      ctx.strokeStyle = `rgba(255, 214, 0, ${s.alpha})`;
      ctx.lineWidth = 4;
      ctx.stroke();
      ctx.restore();
    }

    for (const p of this.particles) {
      ctx.save();
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
  }

  loop() {
    if (this.freezeFrames > 0) {
      this.freezeFrames--;
      requestAnimationFrame(this.loop);
      return;
    }

    // While on Home Menu, just animate fighters gently in idle stance in the background
    if (this.matchState === 'menu') {
      const empty = this.ai.createEmptyInput();
      this.p1.update(empty, this.p2);
      this.p2.update(empty, this.p1);
      this.drawArena();
      this.p1.draw(this.ctx);
      this.p2.draw(this.ctx);
      requestAnimationFrame(this.loop);
      return;
    }

    // 2-PC Online Guest Mode
    if (this.gameMode === 'online' && this.net.connected && this.net.role === 'guest') {
      const myInput = this.gatherPrimaryInput();
      this.net.send({ type: 'guest_input', input: myInput });
    } else {
      // Authoritative Simulation (Offline AI, Offline PvP, or 2-PC Online Host)
      if (this.matchState === 'fighting') {
        const inputP1 = this.gatherPrimaryInput();
        let inputP2;

        if (this.gameMode === 'ai') {
          inputP2 = this.ai.update();
        } else if (this.gameMode === 'local2p') {
          inputP2 = this.gatherLocalP2Input();
        } else if (this.gameMode === 'online') {
          inputP2 = this.remoteP2Input || this.ai.createEmptyInput();
        }

        this.p1.update(inputP1, this.p2);
        this.p2.update(inputP2, this.p1);
      } else if (this.matchState === 'round_over' || this.matchState === 'match_over') {
        const empty = this.ai.createEmptyInput();
        this.p1.update(empty, this.p2);
        this.p2.update(empty, this.p1);
      }

      if (this.gameMode === 'online' && this.net.connected && this.net.role === 'host') {
        this.net.send({
          type: 'host_state',
          p1: this.p1.serialize(),
          p2: this.p2.serialize(),
          roundNumber: this.roundNumber,
          roundTime: this.roundTime,
          matchState: this.matchState,
          events: this.pendingNetEvents
        });
        this.pendingNetEvents = [];
      }
    }

    this.updateFX();
    this.updateHUD();

    this.ctx.save();
    if (this.screenShake > 0) {
      const shakeX = (Math.random() - 0.5) * this.screenShake * 3;
      const shakeY = (Math.random() - 0.5) * this.screenShake * 3;
      this.ctx.translate(shakeX, shakeY);
    }

    this.drawArena();
    this.p1.draw(this.ctx);
    this.p2.draw(this.ctx);
    this.drawFX();

    this.ctx.restore();

    requestAnimationFrame(this.loop);
  }
}

window.addEventListener('DOMContentLoaded', () => {
  new StickmanGame();
});
